def transform(grid):
    h, w = len(grid), len(grid[0])
    # ARC pattern: colors in the sparse speckle palette are overlays; substantial
    # connected regions are the underlying picture. Treat small components as noise.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            comps.append((color, comp))
    # identify sparse-noise colors by their low total frequency (the test's large
    # monochrome blocks and background are retained).
    totals = Counter(v for row in grid for v in row)
    noise_colors = {color for color, n in totals.items() if n <= max(4, h*w//100)}
    noise = {(r,c) for color, comp in comps if color in noise_colors for r,c in comp}
    out = [row[:] for row in grid]
    for r,c in noise:
        counts = Counter()
        # Local majority excluding all overlay pixels.
        for radius in (1,2,3):
            counts.clear()
            for y in range(max(0,r-radius), min(h,r+radius+1)):
                for x in range(max(0,c-radius), min(w,c+radius+1)):
                    if (y,x) != (r,c) and (y,x) not in noise:
                        counts[grid[y][x]] += 1
            if counts:
                break
        if counts:
            out[r][c] = counts.most_common(1)[0][0]
    return out

